import '../../../core/constants/firebase_collections.dart';

/// Represents aggregated AI activity and telemetry statistics for a specific month.
///
/// Partitioned by year-month keys (e.g., '2026-10') inside the parent `usageSummaries` document.
class MonthlyUsageData {
  /// Total number of successful AI requests executed in this billing month.
  final int requestCount;

  /// Total number of prompt/input tokens processed by the AI provider this month.
  final int inputTokens;

  /// Total number of completion/output tokens generated by the AI provider this month.
  final int outputTokens;

  /// Total tokens consumed this month (`inputTokens + outputTokens`).
  final int totalTokens;

  /// Total number of images generated this month (e.g. via DALL-E or Imagen).
  final int imageCount;

  /// Total number of PDF documents parsed and analyzed this month.
  final int pdfCount;

  /// Cumulative estimated dollar expenditure in USD incurred during this month.
  final double estimatedCostUsd;

  const MonthlyUsageData({
    this.requestCount = 0,
    this.inputTokens = 0,
    this.outputTokens = 0,
    this.totalTokens = 0,
    this.imageCount = 0,
    this.pdfCount = 0,
    this.estimatedCostUsd = 0.0,
  });

  /// Creates an empty record with all metrics initialized to zero.
  factory MonthlyUsageData.empty() => const MonthlyUsageData();

  /// Deserializes a monthly data map from Firestore snapshot.
  factory MonthlyUsageData.fromMap(Map<String, dynamic> data) {
    return MonthlyUsageData(
      requestCount: (data[FirebaseCollections.summaryFieldRequestCount] as num?)
              ?.toInt() ??
          0,
      inputTokens:
          (data[FirebaseCollections.usageFieldInputTokens] as num?)?.toInt() ??
              0,
      outputTokens:
          (data[FirebaseCollections.usageFieldOutputTokens] as num?)?.toInt() ??
              0,
      totalTokens:
          (data[FirebaseCollections.usageFieldTotalTokens] as num?)?.toInt() ??
              0,
      imageCount:
          (data[FirebaseCollections.usageFieldImageCount] as num?)?.toInt() ??
              0,
      pdfCount:
          (data[FirebaseCollections.usageFieldPdfCount] as num?)?.toInt() ?? 0,
      estimatedCostUsd:
          (data[FirebaseCollections.summaryFieldEstimatedCostUsd] as num?)
                  ?.toDouble() ??
              0.0,
    );
  }

  /// Serializes monthly metrics into a Firestore map.
  Map<String, dynamic> toMap() {
    return {
      FirebaseCollections.summaryFieldRequestCount: requestCount,
      FirebaseCollections.usageFieldInputTokens: inputTokens,
      FirebaseCollections.usageFieldOutputTokens: outputTokens,
      FirebaseCollections.usageFieldTotalTokens: totalTokens,
      FirebaseCollections.usageFieldImageCount: imageCount,
      FirebaseCollections.usageFieldPdfCount: pdfCount,
      FirebaseCollections.summaryFieldEstimatedCostUsd: estimatedCostUsd,
    };
  }

  /// True if there is any recorded request activity, token spend, or media generation this month.
  bool get hasActivity => requestCount > 0 || totalTokens > 0 || imageCount > 0;

  /// Human-readable formatted dollar cost, e.g. "\$2.80".
  String get formattedCost => '\$${estimatedCostUsd.toStringAsFixed(2)}';
}
